parameters.jsCode:
// DETERMINISTIC slot engine — replaces the LLM "Propose 3 Available Times" step.
// Builds merged busy intervals over the search window, subtracts them from the
// Mon-Fri 10:00-18:00 ET working grid, honours a lead time + a symmetric buffer,
// slices to the requested duration, and picks 3 VARIED slots (>=2 distinct days).
// Output feeds the existing Sonnet writer verbatim ("DO NOT CHANGE THESE").
//
// Input: aggregated window events on $json.data (from 'Aggregate Busy Events'),
//        durationMinutes + search window from 'Search Window Fields'.

function safeGet(nodeName) {
  try { return $(nodeName).item.json || {}; } catch (e) { return {}; }
}
const win = safeGet('Search Window Fields');

// ---- Config constants ----
const TZ = 'America/New_York';
const WORK_START_HOUR = 10;   // 10:00 ET
const WORK_END_HOUR = 18;     // 18:00 ET
const LEAD_MINUTES = 120;     // no slot starting within 2h of now
const BUFFER_MINUTES = 15;    // pad each busy event +/- 15 min before testing
const SLOT_STEP_MINUTES = 30; // grid granularity for candidate starts

let durationMinutes = parseInt(win.durationMinutes, 10);
if (!durationMinutes || durationMinutes <= 0) durationMinutes = 30;

// ---- Validate / repair search window ----
const now = DateTime.now().setZone(TZ);
let startStr = (win.searchStartDate || '').trim();
let endStr = (win.searchEndDate || '').trim();

function validDate(s) { return /^\d{4}-\d{2}-\d{2}$/.test(s) && DateTime.fromISO(s, { zone: TZ }).isValid; }

if (!validDate(startStr)) startStr = now.toFormat('yyyy-MM-dd');
if (!validDate(endStr)) endStr = now.plus({ days: 14 }).toFormat('yyyy-MM-dd');

let winStart = DateTime.fromISO(startStr, { zone: TZ }).startOf('day');
let winEnd = DateTime.fromISO(endStr, { zone: TZ }).endOf('day');

// Swap if start > end.
if (winStart > winEnd) { const t = winStart; winStart = winEnd.startOf('day'); winEnd = t.endOf('day'); }
// Never search the past.
if (winStart < now.startOf('day')) winStart = now.startOf('day');
// Widen if window is too tight to plausibly yield 3 varied business-day slots.
if (winEnd.diff(winStart, 'days').days < 4) winEnd = winStart.plus({ days: 14 }).endOf('day');

// ---- Gather + filter busy events ----
let events = [];
try {
  if (Array.isArray($json.data)) events = $json.data;
  else events = $input.all().map(i => i.json).filter(Boolean);
} catch (e) { events = []; }

const invitee = 'alex@ahbadvisors.com';
const RECLAIM_A = 'This AI-powered event was created by Reclaim.ai';
const RECLAIM_B = 'This event was created by Reclaim';
const TASK_DETAIL = "Only you can see this Task's event details. It will show as busy to others and automatically reschedule if booked over.";

const busy = []; // {start,end} epoch ms, buffer-padded
for (const ev of events) {
  if (!ev) continue;
  const transparency = ev.transparency || 'opaque';
  const status = ev.status || 'confirmed';
  const desc = ev.description || '';
  const title = ev.summary || '';
  if (transparency === 'transparent') continue;
  if (status === 'cancelled') continue;
  let declined = false;
  for (const a of (ev.attendees || [])) {
    const email = (a.email || '').toLowerCase();
    if ((email === invitee || a.self === true) && a.responseStatus === 'declined') { declined = true; break; }
  }
  if (declined) continue;
  if (desc.includes(RECLAIM_A)) continue;
  if (desc.includes(RECLAIM_B)) continue;
  if (desc.includes(TASK_DETAIL)) continue;
  if (title.toLowerCase().includes('decompress')) continue;
  // All-day banners do not block working-hours slots.
  const isAllDay = !!(ev.start && ev.start.date && !ev.start.dateTime);
  if (isAllDay) continue;
  const sISO = (ev.start && (ev.start.dateTime || ev.start.date)) || '';
  const eISO = (ev.end && (ev.end.dateTime || ev.end.date)) || '';
  const s = sISO ? new Date(sISO).getTime() : NaN;
  const e = eISO ? new Date(eISO).getTime() : NaN;
  if (isNaN(s) || isNaN(e)) continue;
  busy.push({ start: s - BUFFER_MINUTES * 60000, end: e + BUFFER_MINUTES * 60000 });
}

// Merge overlapping busy intervals.
busy.sort((a, b) => a.start - b.start);
const merged = [];
for (const b of busy) {
  if (merged.length && b.start <= merged[merged.length - 1].end) {
    merged[merged.length - 1].end = Math.max(merged[merged.length - 1].end, b.end);
  } else {
    merged.push({ start: b.start, end: b.end });
  }
}
function isFree(slotStart, slotEnd) {
  for (const m of merged) { if (slotStart < m.end && slotEnd > m.start) return false; }
  return true;
}

// ---- Walk the working grid, collect candidates ----
const earliestStartMs = now.plus({ minutes: LEAD_MINUTES }).toMillis();
const slotMs = durationMinutes * 60000;
const stepMs = SLOT_STEP_MINUTES * 60000;

const candidates = []; // {startDT, endDT}
let day = winStart.startOf('day');
const lastDay = winEnd.startOf('day');
while (day <= lastDay) {
  const wd = day.weekday; // 1=Mon .. 7=Sun
  if (wd >= 1 && wd <= 5) {
    let cursor = day.set({ hour: WORK_START_HOUR, minute: 0, second: 0, millisecond: 0 });
    const dayEnd = day.set({ hour: WORK_END_HOUR, minute: 0, second: 0, millisecond: 0 });
    while (cursor.plus({ minutes: durationMinutes }) <= dayEnd) {
      const sMs = cursor.toMillis();
      const eMs = sMs + slotMs;
      if (sMs >= earliestStartMs && isFree(sMs, eMs)) {
        candidates.push({ startDT: cursor, endDT: cursor.plus({ minutes: durationMinutes }) });
      }
      cursor = cursor.plus({ minutes: SLOT_STEP_MINUTES });
    }
  }
  day = day.plus({ days: 1 });
}

// ---- Pick 3 VARIED slots: prefer distinct days; avoid two same-morning ----
function partOfDay(dt) { return dt.hour < 12 ? 'am' : 'pm'; }
const picked = [];
const usedDayKeys = new Set();
// Pass 1: first free slot on each distinct day.
for (const c of candidates) {
  const key = c.startDT.toFormat('yyyy-MM-dd');
  if (!usedDayKeys.has(key)) { picked.push(c); usedDayKeys.add(key); }
  if (picked.length >= 3) break;
}
// Pass 2: if <3, backfill with same-day slots in a different part of day.
if (picked.length < 3) {
  for (const c of candidates) {
    if (picked.length >= 3) break;
    if (picked.some(p => p.startDT.toMillis() === c.startDT.toMillis())) continue;
    const sameDaySamePart = picked.some(p =>
      p.startDT.toFormat('yyyy-MM-dd') === c.startDT.toFormat('yyyy-MM-dd') &&
      partOfDay(p.startDT) === partOfDay(c.startDT));
    if (!sameDaySamePart) picked.push(c);
  }
}
// Pass 3: last resort — any remaining distinct candidates.
if (picked.length < 3) {
  for (const c of candidates) {
    if (picked.length >= 3) break;
    if (picked.some(p => p.startDT.toMillis() === c.startDT.toMillis())) continue;
    picked.push(c);
  }
}
picked.sort((a, b) => a.startDT.toMillis() - b.startDT.toMillis());

// ---- Format output ----
const slots = picked.slice(0, 3).map(p => ({
  Date: p.startDT.toFormat('cccc, LLLL d'),          // e.g. "Monday, July 20"
  Start: p.startDT.toFormat('h:mm a') + ' ET',
  End: p.endDT.toFormat('h:mm a') + ' ET',
  startISO: p.startDT.toISO(),
  endISO: p.endDT.toISO()
}));

const proposedTimesText = slots.map(s => `- ${s.Date}: ${s.Start} to ${s.End}`).join('\n');
const enoughSlots = slots.length >= 3;

return [{
  json: {
    slots,
    proposedTimesText,
    slotCount: slots.length,
    enoughSlots,
    durationMinutes,
    searchStartResolved: winStart.toFormat('yyyy-MM-dd'),
    searchEndResolved: winEnd.toFormat('yyyy-MM-dd'),
    summaryForEA: enoughSlots
      ? `${slots.length} available ${durationMinutes}-min slots found between ${winStart.toFormat('LLL d')} and ${winEnd.toFormat('LLL d')}.`
      : `Only ${slots.length} slot(s) found in the working-hours grid between ${winStart.toFormat('LLL d')} and ${winEnd.toFormat('LLL d')}; widen the window or review manually.`
  }
}];
